index 76d1577..eb27e49 100644
--- a/src/core/project.ts
+++ b/src/core/project.ts
@@ -6,12 +6,50 @@ export interface Record {
   warns: readonly string[];
 }

+const semanticFingerprint = (text: string): Set<string> => {
+  const keywordPatterns = [
+    /operational|operate|operating|ops/i,
+    /stateful|state management/i,
+    /always.on|always-on|running|background/i,
+    /cache|caching/i,
+    /service|infrastructure|component/i,
+    /managed|manageable/i,
+  ];
+
+  const fingerprint = new Set<string>();
+  for (const pattern of keywordPatterns) {
+    if (pattern.test(text)) {
+      fingerprint.add(pattern.source);
+    }
+  }
+  return fingerprint;
+};
+
+const fingerprintKey = (fp: Set<string>): string => Array.from(fp).sort().join("|");
+
+const deduplicateEntries = (entries: readonly string[]): string[] => {
+  const seen = new Map<string, string>();
+  for (const entry of entries) {
+    const fp = semanticFingerprint(entry);
+    const key = fingerprintKey(fp);
+
+    const existing = seen.get(key);
+    if (!existing || entry.length < existing.length) {
+      seen.set(key, entry);
+    }
+  }
+  return Array.from(seen.values());
+};
+
 export const project = (records: readonly Record[]): string => {
   const lines: string[] = [];
   for (const record of records) {
-    for (const entry of record.ruledOut) lines.push(`- ruled out: ${entry}`);
-    for (const limit of record.limits) lines.push(`- limit: ${limit}`);
-    for (const warn of record.warns) lines.push(`- warn: ${warn}`);
+    for (const entry of deduplicateEntries(record.ruledOut))
+      lines.push(`- ruled out: ${entry}`);
+    for (const limit of deduplicateEntries(record.limits))
+      lines.push(`- limit: ${limit}`);
+    for (const warn of deduplicateEntries(record.warns))
+      lines.push(`- warn: ${warn}`);
   }
   return lines.join("\n");
 };
